// STEM Education – κάνει τον editor εγκαταστάσιμη εφαρμογή που δουλεύει χωρίς internet.
// Τρέχει στο GitHub Actions μετά το «npm run build». Δεν αλλάζει τίποτα στον κώδικα του TurboWarp.
'use strict';
const fs = require('fs');
const path = require('path');

const BUILD = 'build';
const ROOT = process.env.ROOT;                       // π.χ. /scratch-gui/
const VERSION = process.env.VERSION || String(Date.now());
const ORIGIN = 'https://' + String(process.env.OWNER).toLowerCase() + '.github.io';
const EXT_DIR = '/scratch-wedo/';                    // οι επεκτάσεις μας (ίδιο origin)

// Όνομα εφαρμογής: «Scratch» δεν επιτρέπεται για παράγωγα προϊόντα (TRADEMARK του Scratch)
const APP_NAME = 'STEM Blocks';
const APP_FULL_NAME = 'STEM Blocks – STEM Education';

const EXTENSIONS = ['wedo2-gr.js', 'wedo2-en.js', 'microbit-gr.js', 'microbit-en.js', 'nezha-gr.js', 'nezha-en.js',
  'simulations-gr.js', 'simulations-en.js', 'graph-gr.js', 'graph-en.js',
  'device-sensors-gr.js', 'device-sensors-en.js', 'class-dashboard-gr.js', 'class-dashboard-en.js'];
const ext = (f) => ORIGIN + EXT_DIR + f;
const editorLink = (files) => 'editor.html?' + files.map((f) => 'extension=' + encodeURIComponent(ext(f))).join('&');

const ICON_192 = '';
const ICON_512 = '';

// 1. Εικονίδια και manifest
fs.writeFileSync(path.join(BUILD, 'stem-icon-192.png'), Buffer.from(ICON_192, 'base64'));
fs.writeFileSync(path.join(BUILD, 'stem-icon-512.png'), Buffer.from(ICON_512, 'base64'));
const manifest = {
  name: APP_FULL_NAME,
  short_name: APP_NAME,
  description: 'Προγραμματισμός με blocks για micro:bit, Nezha, PlanetX και WeDo 2.0 – λειτουργεί και χωρίς internet.',
  lang: 'el',
  start_url: 'start.html',                // σελίδα επιλογής επεκτάσεων και γλώσσας
  scope: './',
  display: 'standalone',
  background_color: '#0B1F3A',
  theme_color: '#0B1F3A',
  icons: [
    { src: 'stem-icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: 'stem-icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: 'stem-icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' }
  ],
  shortcuts: [
    { name: 'Ελληνικά', short_name: 'Ελληνικά', url: editorLink(['wedo2-gr.js', 'microbit-gr.js', 'graph-gr.js', 'device-sensors-gr.js']) },
    { name: 'English', short_name: 'English', url: editorLink(['wedo2-en.js', 'microbit-en.js', 'graph-en.js', 'device-sensors-en.js']) }
  ]
};
fs.writeFileSync(path.join(BUILD, 'stem-manifest.webmanifest'), JSON.stringify(manifest, null, 2));

// 2. Λίστα αρχείων για αποθήκευση στη συσκευή
const files = [];
const walk = (dir) => {
  for (const name of fs.readdirSync(dir)) {
    const full = path.join(dir, name);
    if (fs.statSync(full).isDirectory()) walk(full);
    else files.push(path.relative(BUILD, full).split(path.sep).join('/'));
  }
};
walk(BUILD);
const precache = files
  .filter((f) => !f.endsWith('.map') && f !== 'offline-sw.js' && f !== 'sw.js')
  .map((f) => ROOT + f.split('/').map(encodeURIComponent).join('/'))
  .concat(EXTENSIONS.map((f) => EXT_DIR + f));

// 3. Service worker
const sw = `// STEM Blocks offline service worker – έκδοση ${VERSION}
const VERSION = ${JSON.stringify(VERSION)};
const CACHE = 'stem-blocks-' + VERSION;
const ROOT = ${JSON.stringify(ROOT)};
const EXT_DIR = ${JSON.stringify(EXT_DIR)};
const PRECACHE = ${JSON.stringify(precache)};

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // Ένα-ένα, ώστε ένα αρχείο που λείπει να μη χαλάει όλη την εγκατάσταση
    await Promise.allSettled(PRECACHE.map((url) => cache.add(new Request(url, { cache: 'reload' }))));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('stem-blocks-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

const fromCache = (request) => caches.match(request, { ignoreSearch: true });

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // βιβλιοθήκες TurboWarp κ.λπ.: κανονικά από το internet

  // Σελίδες: πρώτα το internet (για ενημερώσεις), αλλιώς η αποθηκευμένη
  if (request.mode === 'navigate' && url.pathname.startsWith(ROOT)) {
    event.respondWith((async () => {
      try {
        const response = await fetch(request);
        if (response.ok) (await caches.open(CACHE)).put(url.pathname, response.clone());
        return response;
      } catch (e) {
        return (await fromCache(url.pathname)) || (await fromCache(ROOT + 'editor.html')) || Response.error();
      }
    })());
    return;
  }

  // Επεκτάσεις: άμεσα από τη συσκευή, ενημέρωση στο παρασκήνιο όταν υπάρχει internet
  if (url.pathname.startsWith(EXT_DIR)) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match(url.pathname);
      const update = fetch(request).then((response) => {
        if (response.ok) cache.put(url.pathname, response.clone());
        return response;
      }).catch(() => cached);
      return cached || update;
    })());
    return;
  }

  // Υπόλοιπα αρχεία του editor: από τη συσκευή, αλλιώς από το internet
  if (url.pathname.startsWith(ROOT)) {
    event.respondWith((async () => {
      const cached = await fromCache(request);
      if (cached) return cached;
      const response = await fetch(request);
      if (response.ok) (await caches.open(CACHE)).put(request, response.clone());
      return response;
    })());
  }
});
`;
fs.writeFileSync(path.join(BUILD, 'offline-sw.js'), sw);

// 4. Σύνδεση manifest + service worker στις σελίδες του editor
const inject = `
<link rel="manifest" href="stem-manifest.webmanifest">
<meta name="theme-color" content="#0B1F3A">
<script>
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', function () {
      navigator.serviceWorker.register('offline-sw.js', { scope: './' }).catch(function (e) { console.warn('offline', e); });
    });
  }
</script>
`;
for (const page of ['start.html', 'editor.html', 'index.html', 'fullscreen.html']) {
  const p = path.join(BUILD, page);
  if (!fs.existsSync(p)) continue;
  const html = fs.readFileSync(p, 'utf8');
  if (!html.includes('stem-manifest.webmanifest')) fs.writeFileSync(p, html.replace('</head>', inject + '</head>'));
}

console.log(`STEM Blocks offline: ${precache.length} files, version ${VERSION}`);

